  // ----------------------------------------------------------
  // EDIT HERE: Contact details. Leave a field empty to hide it.
  // ----------------------------------------------------------
  contact: {
    // EDIT HERE: Business WhatsApp number.
    // Format: country code + number, digits only. No "+", spaces,
    // brackets or hyphens. Example shape: 2348012345678
    // "234XXXXXXXXXX" is a PLACEHOLDER. WhatsApp links stay
    // disabled until it is replaced with a real number.
    whatsappNumber: "234XXXXXXXXXX",

    // EDIT HERE: Telephone, shown to visitors exactly as written,
    // e.g. "+234 801 234 5678". Leave empty if not supplied.
    phone: "",

    // EDIT HERE: Email address. Leave empty if not supplied.
    email: "",

    // EDIT HERE: Business address, if the business wants it public.
    address: "",

    // EDIT HERE: Locations where apartments operate, e.g. ["Area One", "Area Two"].
    operatingLocations: [],

    // EDIT HERE: Full https:// profile URLs. Empty = hidden.
    social: {
      instagram: "",
      facebook: "",
      tiktok: "",
      x: "",
      youtube: ""
    }
  },

  // ----------------------------------------------------------
  // EDIT HERE: WhatsApp message templates.
  //
  // Each entry is one line of the message.
  // Tokens: {{name}} {{location}} {{price}} {{url}}
  // If a line contains a token with no value (for example a
  // missing price), that whole line is removed automatically.
  // Use "" for a blank line.
  // ----------------------------------------------------------
  whatsapp: {
    apartmentMessageLines: [
      "Hello! 👋",
      "",
      "I’m interested in booking {{name}}.",
      "",
      "Location: {{location}}",
      "Price: {{price}}",
      "",
      "Please could you share the availability, booking requirements, and any additional information about this apartment?",
      "",
      "Apartment details: {{url}}",
      "",
      "Thank you!"
    ],

    // Used by general enquiry buttons that are not tied to an apartment.
    generalMessageLines: [
      "Hello! 👋",
      "",
      "I’d like to ask about the apartments at Edinburgh Royale Apartment.",
      "",
      "Thank you!"
    ],

    // Used when an apartment record has no name.
    fallbackApartmentName: "one of your apartments"
  },

  // ----------------------------------------------------------
  // Airbnb link validation.
  // A booking link is only shown if it is https:// and its host
  // ends with one of these domains. Add a domain if Airbnb gives
  // you a listing link on a regional domain not listed here.
  // ----------------------------------------------------------
  airbnb: {
    allowedHostSuffixes: [
      "airbnb.com",
      "airbnb.co.uk",
      "airbnb.ca",
      "airbnb.com.au",
      "airbnb.ie",
      "airbnb.fr",
      "airbnb.de",
      "airbnb.es",
      "airbnb.it",
      "airbnb.co.za",
      "airbnb.com.ng",
      "abnb.me"
    ],
    bookingNote: "Booking is completed on Airbnb."
  },

  // ----------------------------------------------------------
  // EDIT HERE: SEO defaults.
  // siteUrl: add the live domain (e.g. "https://www.example.com")
  // ONLY when the site is published. Canonical links, social
  // preview URLs and shareable apartment links in WhatsApp
  // messages depend on it. Leave empty during development.
  // ----------------------------------------------------------
  seo: {
    siteUrl: "",
    defaultDescription: "Edinburgh Royale Apartment offers a selection of apartments for short stays. Book on Airbnb or enquire on WhatsApp.",
    titleSeparator: " | ",
    ogImage: ""   // e.g. "assets/images/og-image.jpg" (use a real photo)
  },

  // ----------------------------------------------------------
  // EDIT HERE: Apartments shown in the homepage "Featured" section,
  // by apartment id (see js/data/apartments.js). If empty, apartments
  // marked featured: true are used, then the first three.
